#include <iostream>

// Overloaded functions distinguished by parameter types
int computeSquare(int x) {
    return x * x;
}

double computeSquare(double x) {
    return x * x;
}

// Distinct parameter types including references
void modifyValue(int a, double &b) {
    b = a * 2.5;
}

int main() {
    int intVal = 6;
    double dblVal = 4.5;
    double result = 0.0;

    std::cout << "Square of int: " << computeSquare(intVal) << "\n";
    std::cout << "Square of double: " << computeSquare(dblVal) << "\n";

    modifyValue(intVal, result);
    std::cout << "Modified result: " << result << "\n";

    return 0;
}

#include <iostream>

// Function template definition for determining maximum of three values
template <typename T>
T maximum(T value1, T value2, T value3) {
    T maximumValue = value1;
    if (value2 > maximumValue) {
        maximumValue = value2;
    }
    if (value3 > maximumValue) {
        maximumValue = value3;
    }
    return maximumValue;
}

int main() {
    int i1 = 15, i2 = 42, i3 = 27;
    double d1 = 3.14, d2 = 9.81, d3 = 2.72;
    char c1 = 'A', c2 = 'Z', c3 = 'M';

    std::cout << "Maximum integer: " << maximum(i1, i2, i3) << "\n";
    std::cout << "Maximum double: " << maximum(d1, d2, d3) << "\n";
    std::cout << "Maximum char: " << maximum(c1, c2, c3) << "\n";

    return 0;
}
